/* Exact user-provided logo stored as text so PR diff does not include binary assets. */
:root{--brand-logo-url:url("data:image/png;base64,")}
.logo,.header .logo,#tab-home .hero-mark{--brand-logo-image:var(--brand-logo-url);background-color:#000!important;background-image:var(--brand-logo-image)!important;background-position:center!important;background-size:cover!important;background-repeat:no-repeat!important;color:transparent!important;font-size:0!important;overflow:hidden!important}
.header .logo::before,.header .logo::after,.hero-mark::before,.hero-mark::after{display:none!important}
